<template><div><header class="admin-page-header"><div><h1>待审核歌曲</h1><p>按状态查看并处理歌曲。</p></div><div class="service-status"><CircleCheck :size="17"/>服务正常</div></header><div class="admin-toolbar"><el-select v-model="status" aria-label="歌曲状态" @change="reload"><el-option label="已提交" value="SUBMITTED"/><el-option label="已发布" value="PUBLISHED"/><el-option label="已锁定" value="LOCKED"/><el-option label="草稿" value="DRAFT"/></el-select><el-button :loading="loading" @click="reload"><RefreshCw :size="17"/>刷新</el-button></div><AdminState v-if="loading" kind="loading" message="正在加载歌曲…"/><AdminState v-else-if="error" kind="error" :message="error"/><AdminState v-else-if="!page.items.length" kind="empty" message="当前状态下没有歌曲。"/><template v-else><el-table :data="page.items" stripe><el-table-column prop="id" label="ID" width="76"/><el-table-column label="歌曲" min-width="180"><template #default="scope"><strong>{{scope.row.title}}</strong><small class="cell-secondary">{{scope.row.artistStageName||`歌手 #${scope.row.artistUserId}`}}</small></template></el-table-column><el-table-column prop="status" label="状态" width="120"><template #default="scope"><span class="status-value">{{statusText(scope.row.status)}}</span></template></el-table-column><el-table-column prop="playCount" label="播放" width="90"/><el-table-column label="操作" width="190" fixed="right"><template #default="scope"><el-button v-if="scope.row.status==='PENDING_REVIEW'" type="text" @click="publish(scope.row)">发布</el-button><el-button class="danger-text" type="text" @click="lock(scope.row)">锁定</el-button></template></el-table-column></el-table><el-pagination background layout="prev, pager, next" :current-page="page.page+1" :page-size="page.size" :total="page.totalItems" @current-change="changePage"/></template></div></template>
<script>import{CircleCheck,RefreshCw}from'lucide-vue';import{adminApi}from'../api/index.js';import AdminState from'../components/AdminState.vue';import{adminProblemMessage}from'../ui/admin-model.js';export default{name:'TracksView',components:{AdminState,CircleCheck,RefreshCw},data:()=>({status:'SUBMITTED',loading:true,error:'',page:{items:[],page:0,size:20,totalItems:0,totalPages:0}}),async mounted(){await this.reload();},methods:{statusText(value){return{DRAFT:'草稿',PENDING_REVIEW:'已提交',PUBLISHED:'已发布',LOCKED:'已锁定'}[value]||value;},async reload(page=this.page.page||0){this.loading=true;this.error='';try{this.page=await adminApi.tracks({status:this.status,page,size:20});}catch(problem){this.error=adminProblemMessage(problem);}finally{this.loading=false;}},changePage(value){this.reload(value-1);},async publish(row){try{await this.$confirm(`确认发布“${row.title}”？`,'发布歌曲',{confirmButtonText:'发布',cancelButtonText:'取消',type:'warning'});await adminApi.publishTrack(row.id);await this.reload();this.$message.success('歌曲已发布。');}catch(problem){if(problem!=='cancel'&&problem!=='close')this.$message.error(adminProblemMessage(problem));}},async lock(row){try{await this.$confirm(`锁定后“${row.title}”将无法播放，确认继续？`,'锁定歌曲',{confirmButtonText:'锁定',cancelButtonText:'取消',type:'warning'});await adminApi.lockTrack(row.id);await this.reload();this.$message.success('歌曲已锁定。');}catch(problem){if(problem!=='cancel'&&problem!=='close')this.$message.error(adminProblemMessage(problem));}}}};</script>
